head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.fileSizeLimit = 104857600; // 100메가
scwin.isSuspn = false;
scwin.isReSuspn = false;
scwin.isStatusUpdate = false;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.TR_JOB;
scwin.vBzProcsNo, scwin.vCorpRegNo;
scwin.fileTpCdarr = ["011", "021", "022", "023", "031", "041", "051", "061", "062", "063", "", "071", "081", "091", "101", "102", "103", "111", "121", "131", "132", "133", "141"];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.setTrJob();
        await scwin.searchCode();
        await scwin.grdSearchCode();
        await scwin.setSkilValueInstCdCmb();
        // fn_setFileInfo();
        await scwin.grdList();
        buttonSet.setSaveInfo(btn_Save, scwin.save);
        buttonSet.setUpdateInfo(btn_Update, scwin.update);
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete);
        if (scwin.TR_JOB !== "I") {
            await scwin.commList();
            await scwin.fileList();
            buttonSet.setUpdateStatus();
        } else {
            // 기본정보 데이터셋 초기화
            const sbmOptions = {
                id : "sbm_dts_info",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_info=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_info.insertRow();
            rdo_SKIL_BZ_TP_CD.setValue("01");
            rdo_VALU_INST_APPL_CNT.setValue("2");
            // 첨부파일 데이터셋 초기화
            const sbmOptions2 = {
                id : "sbm_dts_fileInfo",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_fileInfo=body.content",
                isProcessMsg : false
            };

            const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
            // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            buttonSet.setInsertStatus();
        }
        await scwin.setCmbTxt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07401.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_info_OnLoadError
 * @description dts_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_info_OnLoadError = function() {

};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07401.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.isStatusUpdate) {
            $c.lc.fn_alertMsg('S1');
        } else {
            $c.lc.fn_alertMsg('S');
        }
        scwin.parentRefresh();
        if (scwin.TR_JOB === "D") {
            await $c.win.closePopup();
        } else {
            await scwin.commList();
            await scwin.fileList();
            buttonSet.setUpdateStatus();
            await scwin.setCmbTxt();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07401.trs_Save_OnSuccess" });
    }
};

