/**
 * @method
 * @name cmb_SKIL_VALU_INST_CD2_onselchange
 * @description cmb_SKIL_VALU_INST_CD2 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_SKIL_VALU_INST_CD2_onselchange = async function() {
    try {
        let skilValuInstCd2 = cmb_SKIL_VALU_INST_CD2.getValue();
        let skilValuInstCd1 = cmb_SKIL_VALU_INST_CD1.getValue();
        if (skilValuInstCd1 !== "" && skilValuInstCd2 === skilValuInstCd1) {
            await $c.win.alert("평가기관1과 동일한값입니다");
            cmb_SKIL_VALU_INST_CD2.setValue("");
            cmb_SKIL_VALU_INST_CD2.focus();
            return;
        }
        let skilValuInstText2 = $c.cp.valueOfIndex(cmb_SKIL_VALU_INST_CD2, "TEXT", cmb_SKIL_VALU_INST_CD2.getSelectedIndex());
        if (skilValuInstText2.indexOf("제척") > -1) {
            await $c.win.alert("평가기관에 제척기관은 선택할 수 없습니다");
            cmb_SKIL_VALU_INST_CD2.setValue("");
            cmb_SKIL_VALU_INST_CD2.focus();
            return;
        }
        scwin.valuInstCd2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07401.cmb_SKIL_VALU_INST_CD2_onselchange" });
    }
};

/**
 * @method
 * @name cmb_SKIL_VALU_INST_CD1_onselchange
 * @description cmb_SKIL_VALU_INST_CD1 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_SKIL_VALU_INST_CD1_onselchange = async function() {
    try {
        let skilValuInstCd2 = cmb_SKIL_VALU_INST_CD2.getValue();
        let skilValuInstCd1 = cmb_SKIL_VALU_INST_CD1.getValue();
        if (skilValuInstCd2 !== "" && skilValuInstCd2 === skilValuInstCd1) {
            await $c.win.alert("평가기관2와 동일한값입니다");
            cmb_SKIL_VALU_INST_CD1.setValue("");
            cmb_SKIL_VALU_INST_CD1.focus();
            return;
        }
        let skilValuInstText1 = $c.cp.valueOfIndex(cmb_SKIL_VALU_INST_CD1, "TEXT", cmb_SKIL_VALU_INST_CD1.getSelectedIndex());
        if (skilValuInstText1.indexOf("제척") > -1) {
            await $c.win.alert("평가기관에 제척기관은 선택할 수 없습니다");
            cmb_SKIL_VALU_INST_CD1.setValue("");
            cmb_SKIL_VALU_INST_CD1.focus();
            return;
        }
        scwin.valuInstCd1();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07401.cmb_SKIL_VALU_INST_CD1_onselchange" });
    }
};

