/**
 * @method
 * @name searchCode
 * @description 콤보박스 값 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "ONECOM_APPL_RSN_CD",
        cnm: "cmb_ONECOM_APPL_RSN_CD"
    }, {
        cid: "SKIL_VALU_PROG_STAT_CD",
        cnm: "cmb_SKIL_VALU_PROG_STAT_CD"
    }, {
        cid: "SKIL_VALU_GRD_CD",
        cnm: "cmb_SKIL_VALU_GRD_CD1"
    }, {
        cid: "SKIL_VALU_GRD_CD",
        cnm: "cmb_SKIL_VALU_GRD_CD2"
    }, {
        cid: "SPECY_VALU_IND_CLSS_CD",
        cnm: "cmb_SPECY_VALU_IND_CLSS_CD"
    }, {
        cid: "SPECY_VALU_IND_CLSS_CD",
        cnm: "cmb_SPECY_VALU_IND_CLSS_CD2"
    }, {
        cid: "SPECY_VALU_SKIL_CLSS_CD",
        cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD"
    }, {
        cid: "SPECY_VALU_SKIL_CLSS_CD",
        cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD2"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^ ";
        if (i === 0) strCbd = "^직접입력";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                const cmbValue = dts_Cod.getCellData(j, "VALUE");
                const cmbText = dts_Cod.getCellData(j, "TEXT");
                strCbd = strCbd + (strCbd === "" ? "" : ",") + cmbValue + "^" + cmbText;
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name grdSearchCode
 * @description grd Search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grdSearchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
