    for (k = 1; k <= dts_GrdCdList.getRowCount(); k++) {
        strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_GrdCdList.getCellData(k, "VALUE") + ":" + dts_GrdCdList.getCellData(k, "TEXT");
