    $c.cm.setColumnProp(grd_LeadCom, 'LEADCOM_MBR_NO', 'Data', strCbdReason);
};

/**
 * @method
 * @name trs
 * @description 트랜잭션 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    let VListBzTpCd;
    let param = "";
    let vScrenProcTpCd;
    let listProcsStatCd = dts_info.getCellData(dts_info.getRowPosition(), "LIST_PROCS_STAT_CD");
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        listProcsStatCd = "33";
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        if (scwin.isSuspn) {
            listProcsStatCd = "11";
        }
        if (scwin.isReSuspn) {
            listProcsStatCd = dts_PROCS_STAT_CD.getCellData(1, "LIST_PROCS_STAT_CD");
        }
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    scwin.isStatusUpdate = false;
    trs_Save.KeyName = "toinb_dataid4";
    param = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=99999" + ",LIST_BZ_TP_CD=760" + ",LIST_PROCS_STAT_CD=" + listProcsStatCd;
    if (scwin.TR_JOB === "I") {
        dts_info.setCellData(1, "REG_ID", js_id);
    }
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "dts_info,dts_fileInfo,dts_LeadCom,dts_ExecInstList",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

