/**
 * @method
 * @name checkSuspnDd
 * @description 철회일이 입력되었는지 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSuspnDd = async function() {
    const suspnDd = dts_info.getCellData(dts_info.getRowPosition(), "ASSGN_SUSPN_DD");
    const oriSuspnDd = dts_info.getCellData(dts_info.getRowPosition(), "ORI_ASSGN_SUSPN_DD");
    if (oriSuspnDd === "" && suspnDd.length === 8) {
        // 철회일이 없었는데 새로 입력된 경우
        scwin.isSuspn = true;
    } else {
        scwin.isSuspn = false;
    }
    if (suspnDd === "" && oriSuspnDd.length === 8) {
        // 철회일이 있었는데 지운경우
        scwin.isReSuspn = true;
        const sbmOptions = {
            id : "sbm_dts_PROCS_STAT_CD",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_PROCS_STAT_CD=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        scwin.isReSuspn = false;
    }
};

