/**
 * @method
 * @name setTrJob
 * @description 부모창 업무처리번호 여부로 신규, 수정 설정
 * @returns {void}
 * @hidden N
 */
scwin.setTrJob = function() {
    let parentWin = $c.frame.path("../");
    if (parentWin.scwin.vBzProcsNo.length > 0) {
        scwin.TR_JOB = "U";
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    } else {
        scwin.TR_JOB = "I";
    }
};

/**
 * @method
 * @name checkForm
 * @description 유효성 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const comNm = $c.ut.trim(txb_COM_NM.getValue());
    const coreValuObjNm = $c.ut.trim(txb_CORE_VALU_OBJ_NM.getValue());
    const assgnApplDd = edt_ASSGN_APPL_DD.getValue();
    if (comNm === "") {
        await $c.win.alert("회사명은 필수로 입력하여야 합니다");
        txb_COM_NM.focus();
        return false;
    }
    if (assgnApplDd === "") {
        await $c.win.alert("배정신청일은 필수로 입력하여야 합니다");
        edt_ASSGN_APPL_DD.focus();
        return false;
    }
    if (!await scwin.dateCheck(edt_SKIL_VALU_ASSGN_DD, "배정일")) {
        return false;
    }
    const valuInstApplCnt = rdo_VALU_INST_APPL_CNT.getValue();
    let oneComApplRsnCd = cmb_ONECOM_APPL_RSN_CD.getValue();
    const oneComApplRsnNm = txb_ONECOM_APPL_RSN_NM.getValue();
    const valuStrtDd = edt_VALU_STRT_DD.getValue();
    const valuStrtDd2 = edt_VALU_STRT_DD2.getValue();
    let skilValuInstCd1 = cmb_SKIL_VALU_INST_CD1.getValue();
    const skilValuInstNm1 = $c.ut.trim(txb_SKIL_VALU_INST_NM1.getValue());
    if (valuStrtDd !== "") {
        if (skilValuInstCd1 === "" && skilValuInstNm1 === "") {
            cmb_SKIL_VALU_INST_CD1.focus();
            await $c.win.alert("평가시작일을 입력하였다면 평가기관1을 입력하여야 합니다");
            return false;
        }
    }
    if (valuStrtDd2 !== "") {
        if (valuInstApplCnt === 2) {
            let skilValuInstCd2 = cmb_SKIL_VALU_INST_CD2.getValue();
            const skilValuInstNm2 = $c.ut.trim(txb_SKIL_VALU_INST_NM2.getValue());
            if (skilValuInstCd2 === "" && skilValuInstNm2 === "") {
                cmb_SKIL_VALU_INST_CD2.focus();
                await $c.win.alert("평가시작일2을 입력하였다면 평가기관2를 입력하여야 합니다");
                return false;
            }
        }
    }
    const valuRsltDd1 = edt_VALU_RSLT_DD1.getValue();
    const valuRsltDd2 = edt_VALU_RSLT_DD2.getValue();
    if (valuRsltDd1 !== "" && valuStrtDd > valuRsltDd1) {
        await $c.win.alert("평가결과일1은 평가시작일 이후여야 합니다");
        edt_VALU_RSLT_DD1.focus();
        return false;
    }
    if (valuRsltDd2 !== "" && valuStrtDd2 > valuRsltDd2) {
        await $c.win.alert("평가결과일2은 평가시작일2 이후여야 합니다");
        edt_VALU_RSLT_DD2.focus();
        return false;
    }
    const skilValuProgStatCd = cmb_SKIL_VALU_PROG_STAT_CD.getValue();
    const assgnSuspnDd = edt_ASSGN_SUSPN_DD.getValue();
    /*
    if(skilValuProgStatCd == "04" && assgnSuspnDd == ""){
    	alert("진행상태가 '배정중단'인 경우 배정중단일을 입력하여야 합니다");
    	edt_ASSGN_SUSPN_DD.focus();
    	return false;
    }
     */
    let skilValuInstText1 = $c.cp.valueOfIndex(cmb_SKIL_VALU_INST_CD1, "TEXT", cmb_SKIL_VALU_INST_CD1.getSelectedIndex());
    let skilValuInstText2 = $c.cp.valueOfIndex(cmb_SKIL_VALU_INST_CD2, "TEXT", cmb_SKIL_VALU_INST_CD2.getSelectedIndex());
    if (skilValuInstText1.indexOf("제척") > -1) {
        await $c.win.alert("평가기관에 제척기관으로 선택된 기관은 저장할 수 없습니다");
        cmb_SKIL_VALU_INST_CD1.focus();
        return false;
    }
    if (skilValuInstText2.indexOf("제척") > -1) {
        await $c.win.alert("평가기관에 제척기관으로 선택된 기관은 저장할 수 없습니다");
        cmb_SKIL_VALU_INST_CD2.focus();
        return false;
    }
    /*
    if(!checkFileSize()){
    	return false;
    }
     */
    if (!$c.stf.checkMaxLength(txb_COM_NM, txb_COM_NM.maxLength, "법인명")) return false;
    if (!$c.stf.checkMaxLength(txb_REP_NM, txb_REP_NM.maxLength, "대표자명")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_COM_TP_VAL, txb_SPECY_VALU_COM_TP_VAL.maxLength, "기업형태")) return false;
    if (!$c.stf.checkMaxLength(txb_TEL_NO, txb_TEL_NO.maxLength, "연락처 Tel.")) return false;
    if (!$c.stf.checkMaxLength(txb_ADDR, txb_ADDR.maxLength, "본사주소")) return false;
    if (!$c.stf.checkMaxLength(txb_DTL_ADDR, txb_DTL_ADDR.maxLength, "본사주소 상세")) return false;
    if (!$c.stf.checkMaxLength(txb_MAINTR_BK_NM, txb_MAINTR_BK_NM.maxLength, "주거래은행")) return false;
    if (!$c.stf.checkMaxLength(txb_FAX_NO, txb_FAX_NO.maxLength, "연락처 Fax.")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL1, txb_SPECY_VALU_MAJ_PROD_VAL1.maxLength, "제1사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL2, txb_SPECY_VALU_MAJ_PROD_VAL2.maxLength, "제2사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_SPECY_VALU_MAJ_PROD_VAL3, txb_SPECY_VALU_MAJ_PROD_VAL3.maxLength, "제3사업 주요제품및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_NM, txb_APCT_NM.maxLength, "신청자 이름")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_TEL_NO, txb_APCT_TEL_NO.maxLength, "신청자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_APCT_EMAIL, txb_APCT_EMAIL.maxLength, "신청자 이메일")) return false;
    if (!$c.stf.checkMaxLength(txb_CORE_VALU_OBJ_NM, txb_CORE_VALU_OBJ_NM.maxLength, "핵심평가대상")) return false;
    if (!$c.stf.checkMaxLength(txb_MAJ_PROD_NM, txb_MAJ_PROD_NM.maxLength, "주요 제품 및 상품")) return false;
    if (!$c.stf.checkMaxLength(txb_ONECOM_APPL_RSN_NM, txb_ONECOM_APPL_RSN_NM.maxLength, "특례대상여부 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_ADD_EXC_INST_NM, txb_ADD_EXC_INST_NM.maxLength, "그 외 체척기관")) return false;
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "주관사 입력비고")) return false;
    if (!$c.stf.checkMaxLength(txa_INSIDE_REMK, 300, "내부용 비고")) return false;
    if (!$c.stf.checkMaxLength(txb_SKIL_VALU_INST_NM1, txb_SKIL_VALU_INST_NM1.maxLength, "평가기관1 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_SKIL_VALU_INST_NM2, txb_SKIL_VALU_INST_NM2.maxLength, "평가기관2 직접입력")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_CHRG_NM, txb_VALU_INST_CHRG_NM.maxLength, "평가기관1 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_CHRG_NM2, txb_VALU_INST_CHRG_NM2.maxLength, "평가기관2 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_TEL_NO, txb_VALU_INST_TEL_NO.maxLength, "평가기관1 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_TEL_NO2, txb_VALU_INST_TEL_NO2.maxLength, "평가기관2 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_EMAIL, txb_VALU_INST_EMAIL.maxLength, "평가기관1 이메일")) return false;
    if (!$c.stf.checkMaxLength(txb_VALU_INST_EMAIL2, txb_VALU_INST_EMAIL2.maxLength, "평가기관2 이메일")) return false;
    if (!$c.stf.checkMaxLength(txa_EXT_OPN_VALU_RSLT_REMK, 1000, "외부 공개용 평가 결과 관련 비고")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_BROKER_NM, txb_LIST_BROKER_NM.maxLength, "주관사 기타")) return false;
    return true;
};

/**
 * @method
 * @name checkGrid
 * @description check Grid 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkGrid = async function() {
    let comCd, compCdIn;
    for (let i = 1, j = dts_LeadCom.getRowCount(); i <= j; i++) {
        comCd = dts_LeadCom.getCellData(i, "LEADCOM_MBR_NO");
        if (comCd === "") {
            await $c.win.alert("주관사에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (let k = 1, l = dts_LeadCom.getRowCount(); k <= l; k++) {
            if (i === k) continue;
            compCdIn = dts_LeadCom.getCellData(k, "LEADCOM_MBR_NO");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 주관사는 입력할 수 없습니다.");
                return false;
            }
        }
    }
    for (let i = 1, j = dts_ExecInstList.getRowCount(); i <= j; i++) {
        comCd = dts_ExecInstList.getCellData(i, "SPECY_VALU_INST_CD");
        if (comCd === "") {
            await $c.win.alert("제척기관에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (let k = 1, l = dts_ExecInstList.getRowCount(); k <= l; k++) {
            if (i === k) continue;
            compCdIn = dts_ExecInstList.getCellData(k, "SPECY_VALU_INST_CD");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 제척기관은 입력할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm() && await scwin.checkGrid() && await scwin.fncheckInstCheck()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);

        // alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_info.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name changeApplCnt
 * @description 평가기관 신청수에 따른 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeApplCnt = async function() {
    let applCnt = rdo_VALU_INST_APPL_CNT.getValue();
    const valueYn = cmb_ONECOM_APPL_RSN_CD.getValue();
    if (valueYn === "99" && applCnt === "1") {
        await $c.win.alert("특례대상여부가 해당없음인 경우 1사 선택 불가");
        rdo_VALU_INST_APPL_CNT.setValue("2");
        rdo_VALU_INST_APPL_CNT.Reset();
        return;
    }
    if (applCnt === "1") {
        cmb_SKIL_VALU_INST_CD2.setDisabled(true);
        cmb_SKIL_VALU_GRD_CD2.setDisabled(true);
        edt_VALU_RSLT_DD2.setDisabled(true);
        cmb_SKIL_VALU_INST_CD2.setValue("");
        txb_SKIL_VALU_INST_NM2.setValue("");
        cmb_SKIL_VALU_GRD_CD2.setValue("");
        edt_VALU_RSLT_DD2.setValue("");
        txb_SKIL_VALU_INST_NM2.setDisabled(true);
    } else {
        cmb_SKIL_VALU_INST_CD2.setDisabled(false);
        txb_SKIL_VALU_INST_NM2.setDisabled(false);
        cmb_SKIL_VALU_GRD_CD2.setDisabled(false);
        edt_VALU_RSLT_DD2.setDisabled(false);
    }
};

/**
 * @method
 * @name changeApplRsn
 * @description 1사 신청이유 콤보값에 따른 1사 신청이유 직접입력 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeApplRsn = async function() {
    let oneComApplRsnCd = cmb_ONECOM_APPL_RSN_CD.getValue();
    let applCnt = rdo_VALU_INST_APPL_CNT.getValue();
    /*
    if(oneComApplRsnCd == "99"){
    	rdo_VALU_INST_APPL_CNT.Format = "2^2사^,1^1사^Disabled";
    	rdo_VALU_INST_APPL_CNT.Reset();
    }else{
    	rdo_VALU_INST_APPL_CNT.Format = "2^2사^,1^1사";
    	rdo_VALU_INST_APPL_CNT.Reset();
    }
     */
    if (applCnt === "1" && oneComApplRsnCd === "99") {
        // 1사신청인 경우 해당없음 선택불가
        await $c.win.alert("특례대상 여부 '해당없음'인 경우 평가기관 신청수 1사 선택불가");
        rdo_VALU_INST_APPL_CNT.setValue("2");
        cmb_SKIL_VALU_INST_CD2.setDisabled(false);
        txb_SKIL_VALU_INST_NM2.setDisabled(false);
        cmb_SKIL_VALU_GRD_CD2.setDisabled(false);
        edt_VALU_RSLT_DD2.setDisabled(false);
        return;
    }
    if (oneComApplRsnCd === "") {
        txb_ONECOM_APPL_RSN_NM.setDisabled(false);
    } else {
        txb_ONECOM_APPL_RSN_NM.setDisabled(true);
        txb_ONECOM_APPL_RSN_NM.setValue("");
    }
};

