/**
 * @method
 * @name fileClick
 * @description 첨부파일 업로드 처리
 * @param {*} fileDiv fileDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileClick = async function(fileDiv) {
    if (inf_find.getValue() === "") return;
    const fileFullPath = inf_find.getValue();
    const temp = (fileFullPath).split("\\");
    const fileName = temp[temp.length - 1];
    if (await scwin.checkFileNameSize(fileName)) {
        return false;
    }
    const txbFileOb = $p.getComponentById("txb_FILE_NM" + fileDiv);
    txbFileOb.setValue(inf_find.getValue());
    let fileRow = $c.cp.getNameValueRow(dts_fileInfo, "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
    if (fileRow > 0) {
        // 기존파일 존재
        dts_fileInfo.setCellData(fileRow, "fileInfo", fileFullPath);
        dts_fileInfo.setCellData(fileRow, "fileUrl", fileFullPath);
        dts_fileInfo.setCellData(fileRow, "ATTACH_FILE_SZ", inf_find.FileInfo("size"));
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
    } else {
        dts_fileInfo.insertRow();
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "fileInfo", fileFullPath);
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "fileUrl", fileFullPath);
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "ATTACH_FILE_SZ", inf_find.FileInfo("size"));
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "SEQ", scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "SKIL_VALU_ATTACH_FILE_TP_CD", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2));
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_fileInfo.setCellData(dts_fileInfo.getRowCount(), "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
        let deleteIcon = $p.getComponentById("file_delete" + fileDiv);
        deleteIcon.show("");
    }
    inf_find.setValue("");
};

/**
 * @method
 * @name checkFileNameSize
 * @description 파일명 길이 체크
 * @param {*} fileName fileName
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFileNameSize = async function(fileName) {
    const nameByte = $c.stf.getStringSize(fileName);
    const overLen = (nameByte - 80);
    let isValid = false;
    if (overLen > 0) {
        await $c.win.alert("파일명의 최대길이는 80byte입니다. 파일명 길이를 확인하세요 (한글 : 2 byte 숫자,영문 : 1byte)");
        isValid = true;
    }
    return isValid;
};

/**
 * @method
 * @name fncheckInstCheck
 * @description 평가기관에 선택된 제척기관인지 확인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncheckInstCheck = async function() {
    const instCd1 = cmb_SKIL_VALU_INST_CD1.getValue();
    const instCd2 = cmb_SKIL_VALU_INST_CD2.getValue();
    let execInstCd;
    for (let i = 1, j = dts_ExecInstList.getRowCount(); i <= j; i++) {
        execInstCd = dts_ExecInstList.getCellData(i, "SPECY_VALU_INST_CD");
        if (execInstCd !== "") {
            if (execInstCd === instCd1 || execInstCd === instCd2) {
                await $c.win.alert("제척기관은 평가기관으로 선택할수 없습니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name setFileInfo
 * @description 첨부파일 텍스트박스에 설정
 * @returns {void}
 * @hidden N
 */
scwin.setFileInfo = function() {
    let txbFileObj, findRow, fileTpCd, lastName, isTrue;
    const fileDownIcon = "down_file";
    const fileDelIcon = "file_delete";
    for (let i = 1; i <= 23; i++) {
        if (i === 11) continue;
        txbFileObj = $p.getComponentById("txb_FILE_NM" + i);
        findRow = $c.cp.getNameValueRow(dts_fileInfo, "FILE_DIV", scwin.fileTpCdarr[i - 1]);
        const downIcon = $p.getComponentById(fileDownIcon + i);
        let deleteIcon = $p.getComponentById(fileDelIcon + i);
        if (findRow > 0) {
            txbFileObj.setValue(dts_fileInfo.getCellData(findRow, "ATTACH_FILE_NM"));
            isTrue = true;
        } else {
            txbFileObj.setValue("");
            isTrue = false;
        }
        $c.stf.showObj(downIcon, isTrue);
        $c.stf.showObj(deleteIcon, isTrue);
    }
};

/**
 * @method
 * @name fileDelete
 * @description 첨부파일 삭제
 * @param {*} fileDiv fileDiv
 * @returns {void}
 * @hidden N
 */
scwin.fileDelete = function(fileDiv) {
    let txtFileObj, fileRow;
    txtFileObj = $p.getComponentById("txb_FILE_NM" + fileDiv);
    if (txtFileObj.getValue() === "") {
        return;
    } else {
        if (confirm("파일을 삭제하시겠습니까?")) {
            txtFileObj.setValue("");
            fileRow = $c.cp.getNameValueRow(dts_fileInfo, "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
            if (fileRow > 0) {
                dts_fileInfo.removeRow(fileRow);
            }
        }
    }
};

/**
 * @method
 * @name fileDownload
 * @description 첨부파일 다운로드
 * @param {*} fileDiv fileDiv
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function(fileDiv) {
    let fileRow = $c.cp.getNameValueRow(dts_fileInfo, "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
    const isRealFile = dts_fileInfo.getCellData(fileRow, "REAL");
    if (fileRow > 0 && isRealFile === "REAL") {
        const skilValuAttachFileTpCd = scwin.fileTpCdarr[fileDiv - 1].substring(0, 2);
        const seq = scwin.fileTpCdarr[fileDiv - 1].substring(2, 3);
        const bzProcsNo = scwin.vBzProcsNo;
        location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF07041.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&SKIL_VALU_ATTACH_FILE_TP_CD=" + skilValuAttachFileTpCd + "&SEQ=" + seq + "&gubun=43";
    }
};

