/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFileSize = async function() {
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dts_fileInfo.getRowCount(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileInfo.getCellData(i, "ATTACH_FILE_SZ"));
    }
    if (totalFileSize > scwin.fileSizeLimit) {
        await $c.win.alert("업도르 전체 파일용량은 100MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};

