/**
 * @method
 * @name checkSkilBzTpCd
 * @description check Skil Bz Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkSkilBzTpCd = function() {
    const skilBzTpCd = rdo_SKIL_BZ_TP_CD.getValue();
    if ("02" === skilBzTpCd) {
        // 사업모델기업인 경우 산업선택, 기술선택 선택불가
        cmb_SPECY_VALU_IND_CLSS_CD.setDisabled(true);
        cmb_SPECY_VALU_IND_CLSS_CD2.setDisabled(true);
        cmb_SPECY_VALU_SKIL_CLSS_CD.setDisabled(true);
        cmb_SPECY_VALU_SKIL_CLSS_CD2.setDisabled(true);
        cmb_SPECY_VALU_IND_CLSS_CD.setValue("");
        cmb_SPECY_VALU_IND_CLSS_CD2.setValue("");
        cmb_SPECY_VALU_SKIL_CLSS_CD.setValue("");
        cmb_SPECY_VALU_SKIL_CLSS_CD2.setValue("");
    } else {
        cmb_SPECY_VALU_IND_CLSS_CD.setDisabled(false);
        cmb_SPECY_VALU_IND_CLSS_CD2.setDisabled(false);
        cmb_SPECY_VALU_SKIL_CLSS_CD.setDisabled(false);
        cmb_SPECY_VALU_SKIL_CLSS_CD2.setDisabled(false);
    }
};

/**
 * @method
 * @name setBtn
 * @description set Btn 처리
 * @returns {void}
 * @hidden N
 */
scwin.setBtn = function() {
    let listProcsStatCd = dts_info.getCellData(dts_info.getRowPosition(), "LIST_PROCS_STAT_CD");
    const retryYn = dts_info.getCellData(dts_info.getRowPosition(), "RETRY_YN");
    if (listProcsStatCd !== "32") {
        btn_Acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
        btn_Acpt.setDisabled(true);
        btn_Reject.setBackgroundImage("../img/btn_reject_d.gif");
        btn_Reject.setDisabled(true);
    }
    if (retryYn === "Y") {
        btn_RETRY_YN.setBackgroundImage("../img/btn_09.gif");
        btn_RETRY_YN.setDisabled(false);
    } else {
        btn_RETRY_YN.setBackgroundImage("../img/btn_09_d.gif");
        btn_RETRY_YN.setDisabled(true);
    }
};

/**
