 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findRetryYn = async function() {
    scwin.vCorpRegNo = dts_info.getCellData(dts_info.getRowPosition(), "CORP_REG_NO");
    const adjreqUrl = "/lstinvstg/ULDSTF07406.gfm";
    await $c.frame.CreateDialogFrame("ULDSTF07406.gfm", adjreqUrl, "전문평가관리 재신청 리스트", 50, 50, 1300, 300, "window");
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @param {Object} obj 컴포넌트
 * @param {*} objName objName
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function(obj, objName) {
    const date = obj.getValue();
    const validDate = $c.ut.isDate(date);
    if (!validDate) {
        await $c.win.alert(objName + " 유효한 날짜만 입력가능합니다.");
        // edt_SKIL_VALU_ASSGN_DD.focus();

    }
    return validDate;
};
